const tabs=[...document.querySelectorAll('[role="tab"]')];
const examples={summary:{file:'summary',label:'A clear summary of an example video about planning your week.'},timestamps:{file:'timestamps',label:'Three example key takeaways with links to timestamps in the source video.'},recipe:{file:'recipe',label:'An example recipe summary retaining ingredient quantities, temperature, and cooking times.'}};
function selectTab(tab){for(const item of tabs){const selected=item===tab;item.setAttribute('aria-selected',String(selected));item.tabIndex=selected?0:-1;}const example=examples[tab.dataset.example];const image=document.querySelector('#example-image');image.src=`/assets/${example.file}.png`;image.alt=example.label;document.querySelector('#example-panel').setAttribute('aria-labelledby',tab.id);}
for(const tab of tabs){tab.addEventListener('click',()=>selectTab(tab));tab.addEventListener('keydown',event=>{let i=tabs.indexOf(tab);if(event.key==='ArrowRight')i=(i+1)%tabs.length;else if(event.key==='ArrowLeft')i=(i+tabs.length-1)%tabs.length;else if(event.key==='Home')i=0;else if(event.key==='End')i=tabs.length-1;else return;event.preventDefault();selectTab(tabs[i]);tabs[i].focus();});}
